/** SKUs look like "MUG-0001": three capital letters, a dash, four digits. */
export function isValidSku(value) {
  return typeof value === "string" && /^[A-Z]{3}-\d{4}$/.test(value);
}

/** Trims and upper-cases whatever it gets ("  mug-0001 " -> "MUG-0001"). */
export function normalizeSku(value) {
  return String(value).trim().toUpperCase();
}
